// Pull the lead id + any provider fields the intake captured. We do NOT
// invent provider data — if no NPI / provider name is present we pass what
// we have and let the CRM's live NPPES verification return NPI_HOLD.
const lead = $json.lead || $json.payload?.lead || $json.payload || {};
if (!lead.id) {
  throw new Error('lead.created payload missing lead.id — cannot orchestrate pipeline');
}
return [{ json: {
  lead_id: lead.id,
  npi: lead.provider_npi || lead.npi || undefined,
  expected: {
    name: lead.provider_name || undefined,
    organization: lead.provider_organization || undefined,
    city: lead.provider_city || undefined,
    state: lead.provider_state || undefined,
    specialty: lead.provider_specialty || undefined
  }
} }];

